        {
          "event_id": "lite_evt_00287",
          "explanation": "医生要求以护士站或管床医生医嘱单核对，而不是凭记忆改药。",
          "quote": "找护士站或管床医生核对医嘱单"
        }
      ],
      "completion": "complete",
      "explanation": "HO3被触发并完成：家属给出不确定的药名/剂量信息，医生识别为可能误读或记错，要求用医嘱单和医护核对，并将未核实状态纳入不要自行调整、夜间观察和出院前复核计划。",
      "ho_id": "HO3",
      "meaningful_trajectory_impact": true,
      "triggered": true
    },
    {
      "active_model_action": true,
      "citations": [
        {
